    fullYaml:
      'name: deduplicate-events\ndescription: Claim deduplication keys atomically and archive repeated events.\ntype: pipeline\nnamespace: examples\nlabels:\n  category: data-transformation\n  pattern: deduplication\nconfig:\n  input:\n    http_server:\n      address: 127.0.0.1:8080\n      path: /{endpoint:webhooks/signup|events}\n      allowed_verbs:\n        - POST\n  pipeline:\n    threads: 1\n    processors:\n      - mapping: |-\n          root = this\n          let strategy = this.dedup_strategy.or(if this.event_id != null { "event_id" } else { "hash" })\n          let hash = this.format_json().hash("sha256").encode("hex")\n          let event = this\n          let identity = match $strategy {\n            "event_id" => $event.event_id.string()\n            "composite" => $event.event_type.or("unknown") + ":" + $event.source.or("unknown") + ":" + ($event.timestamp.ts_parse("2006-01-02T15:04:05Z").ts_unix() / 60).floor().string()\n            "hash" => $hash\n            _ => throw("Unknown deduplication strategy")\n          }\n          root.dedup_hash = $hash\n          root.dedup_key = ($strategy + ":" + $identity).hash("sha256").encode("hex")\n          root.dedup_strategy = $strategy\n          meta dedup_strategy = $strategy\n          meta dedup_key = root.dedup_key\n          root.is_duplicate = false\n          root.dedup_timestamp = now()\n      # `add` is an atomic claim: only the first concurrent message can own a\n      # deduplication key. Existing keys return a processor error, which the\n      # following catch converts into a duplicate result.\n      - cache:\n          resource: delivered\n          operator: add\n          key: ${! this.dedup_key }\n          value: ${! this.dedup_timestamp }\n          ttl: 1h\n      - mapping: root.is_duplicate = false\n      - catch:\n          - mapping: |-\n              root = this\n              let strategy = metadata("dedup_strategy").or(this.dedup_strategy).or(if this.event_id != null { "event_id" } else { "hash" })\n              root.dedup_strategy = $strategy\n              root.is_duplicate = true\n      - mapping: |-\n          root = this\n          root.dedup_result = {"is_duplicate": this.is_duplicate, "dedup_key": this.dedup_key, "strategy": this.dedup_strategy, "checked_at": now()}\n          root.duplicate_metadata = if this.is_duplicate { {"detected_at": now(), "original_hash": this.dedup_hash, "strategy": this.dedup_strategy} } else { deleted() }\n  output:\n    switch:\n      cases:\n        - check: this.is_duplicate == false\n          output:\n            fallback:\n              - broker:\n                  pattern: fan_out\n                  outputs:\n                    - http_client:\n                        url: ${ANALYTICS_HTTPS_URL}/events\n                        verb: POST\n                        headers:\n                          Authorization: Bearer ${ANALYTICS_API_TOKEN}\n                          Content-Type: application/json\n                        tls:\n                          enabled: true\n                        retries: 3\n                    - kafka:\n                        addresses:\n                          - ${KAFKA_TLS_BROKERS}\n                        topic: unique-events\n                        tls:\n                          enabled: true\n                          root_cas_file: ${KAFKA_CA_FILE}\n                        sasl:\n                          mechanism: SCRAM-SHA-512\n                          user: ${KAFKA_USERNAME}\n                          password: ${KAFKA_PASSWORD}\n              # Failed delivery must release the claim before rejecting the\n              # message so the input can retry it rather than suppress it.\n              - processors:\n                  - cache:\n                      resource: delivered\n                      operator: delete\n                      key: ${! metadata("dedup_key") }\n                reject: downstream delivery failed; deduplication claim released\n        - output:\n            file:\n              path: ${DUPLICATE_ARCHIVE_PATH}/dupes.jsonl\n              codec: lines\n  cache_resources:\n    - label: delivered\n      redis:\n        url: ${DEDUP_REDIS_URL}\n        default_ttl: 1h\n        tls:\n          enabled: true\n          root_cas_file: ${REDIS_CA_FILE}\n',
